'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var Int32Array = require( '@stdlib/array/int32' );
var pkg = require( './../package.json' ).name;
var dgebal = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var JOBS = [
	'permute',
	'scale',
	'both',
	'none'
];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} N - number of elements along each dimension
* @param {string} job - indicates the operations to be performed
* @returns {Function} benchmark function
*/
function createBenchmark( order, N, job ) {
	var scale;
	var out;
	var sa1;
	var sa2;
	var A;

	scale = new Float64Array( N );
	out = new Int32Array( 2 );

	A = uniform( N*N, -10.0, 10.0, {
		'dtype': 'float64'
	});

	if ( isColumnMajor( order ) ) {
		sa1 = 1;
		sa2 = N;
	} else {
		sa1 = N;
		sa2 = 1;
	}

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dgebal( job, N, A, sa1, sa2, 0, out, 1, 0, scale, 1, 0 );
			if ( isnan( z ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var ord;
	var job;
	var N;
	var f;
	var i;
	var j;
	var k;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( i = min; i <= max; i++ ) {
			N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
			for ( j = 0; j < JOBS.length; j++ ) {
				job = JOBS[ j ];
				f = createBenchmark( ord, N, job );
				bench( pkg+'::square_matrix:order='+ord+',job='+job+',size='+(N*N), f );
			}
		}
	}
}

main();
